-- 1: Define table variable
CREATE OR REPLACE TEMPORARY TABLE UTIL.TMP_ADF_COPY_CONTROL (
	ADF_COPY_CONTROL_KEY NUMBER (38,0) NOT NULL, 
	INSERT_DATETIME TIMESTAMP_TZ(9) NOT NULL, 
	LAST_UPDATED_DATETIME TIMESTAMP_TZ(9) NOT NULL, 
	IS_ACTIVE BOOLEAN NOT NULL, 
	IS_INCREMENTAL BOOLEAN NOT NULL, 
	IS_COPY_INTO_FLAG BOOLEAN NOT NULL, 
    IS_PARTITION_BY_DATE BOOLEAN NOT NULL,	
    TRUNCATE_TABLE_FLAG BOOLEAN NOT NULL,
    SOURCE_DATABASE_TYPE VARCHAR NOT NULL, 
	SOURCE_SCHEMA_NAME VARCHAR NOT NULL, 
	SOURCE_TABLE_NAME VARCHAR NOT NULL, 
	SOURCE_LOOKUP_COLUMN_NAME VARCHAR, 
	SOURCE_QUERY VARCHAR NOT NULL, 
	SOURCE_SECRET_VALUE VARCHAR,
	BLOB_QUERY VARCHAR, 
	TARGET_SCHEMA_NAME VARCHAR,
    TARGET_TABLE_NAME VARCHAR, 
	TARGET_DATA_LAKE_PATH VARCHAR NOT NULL, 
    ADF_TRIGGER_NAME VARCHAR,
	SOURCE_DATABASE_NAME VARCHAR,
	IS_HEDIS_RUN_ID_TABLE BOOLEAN NOT NULL,
	IS_PARTITION_BY_STRING BOOLEAN NOT NULL,
	PARTITION_BY_STRING_COLUMN_NAME VARCHAR,
	TARGET_CONTAINER_NAME VARCHAR,
	CONSTRAINT PK_ADF_COPY_CONTROL PRIMARY KEY (ADF_COPY_CONTROL_KEY),
	CONSTRAINT UK_ADF_COPY_CONTROL UNIQUE (TARGET_TABLE_NAME)
	)
	COMMENT = 'Control table for copying tables from databases outside of Snowflake';    

-- 2: Populate the table variable with data
-- This is where you manage your data in source control. You
-- can add and modify entries, but because of potential foreign
-- key contraint violations this script will not delete any
-- removed entries. If you remove an entry then it will no longer
-- be added to new databases based on your schema, but the entry
-- will not be deleted from databases in which the value already exists.

;


-- 3: Insert any new items into the table from the table variable
SELECT TMP.ADF_COPY_CONTROL_KEY, TMP.INSERT_DATETIME, TMP.LAST_UPDATED_DATETIME, TMP.IS_ACTIVE, TMP.IS_INCREMENTAL, TMP.IS_COPY_INTO_FLAG, TMP.IS_PARTITION_BY_DATE, TMP.TRUNCATE_TABLE_FLAG, TMP.SOURCE_DATABASE_TYPE, TMP.SOURCE_SCHEMA_NAME, TMP.SOURCE_TABLE_NAME, TMP.SOURCE_LOOKUP_COLUMN_NAME, TMP.SOURCE_QUERY, TMP.SOURCE_SECRET_VALUE, TMP.BLOB_QUERY, TMP.TARGET_SCHEMA_NAME, TMP.TARGET_TABLE_NAME, TMP.TARGET_DATA_LAKE_PATH, TMP.ADF_TRIGGER_NAME, TMP.SOURCE_DATABASE_NAME, TMP.IS_HEDIS_RUN_ID_TABLE, TMP.IS_PARTITION_BY_STRING, TMP.PARTITION_BY_STRING_COLUMN_NAME, TMP.TARGET_CONTAINER_NAME
FROM UTIL.TMP_ADF_COPY_CONTROL TMP
	LEFT JOIN UTIL.ADF_COPY_CONTROL TB1 ON TB1.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY
WHERE TB1.ADF_COPY_CONTROL_KEY IS NULL;

-- 4: Update any modified values with the values from the table variables
UPDATE UTIL.ADF_COPY_CONTROL LIVE_TABLE
SET
LIVE_TABLE.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY, 
LIVE_TABLE.INSERT_DATETIME = TMP.INSERT_DATETIME, 
LIVE_TABLE.LAST_UPDATED_DATETIME = TMP.LAST_UPDATED_DATETIME, 
LIVE_TABLE.IS_ACTIVE = TMP.IS_ACTIVE, 
LIVE_TABLE.IS_INCREMENTAL = TMP.IS_INCREMENTAL, 
LIVE_TABLE.IS_COPY_INTO_FLAG = TMP.IS_COPY_INTO_FLAG, 
LIVE_TABLE.IS_PARTITION_BY_DATE = TMP.IS_PARTITION_BY_DATE, 
LIVE_TABLE.TRUNCATE_TABLE_FLAG = TMP.TRUNCATE_TABLE_FLAG, 
LIVE_TABLE.SOURCE_DATABASE_TYPE = TMP.SOURCE_DATABASE_TYPE,
LIVE_TABLE.SOURCE_SCHEMA_NAME = TMP.SOURCE_SCHEMA_NAME, 
LIVE_TABLE.SOURCE_TABLE_NAME = TMP.SOURCE_TABLE_NAME, 
LIVE_TABLE.SOURCE_LOOKUP_COLUMN_NAME = TMP.SOURCE_LOOKUP_COLUMN_NAME, 
LIVE_TABLE.SOURCE_QUERY = TMP.SOURCE_QUERY, 
LIVE_TABLE.SOURCE_SECRET_VALUE  = TMP.SOURCE_SECRET_VALUE, 
LIVE_TABLE.BLOB_QUERY = TMP.BLOB_QUERY, 
LIVE_TABLE.TARGET_SCHEMA_NAME = TMP.TARGET_SCHEMA_NAME, 
LIVE_TABLE.TARGET_TABLE_NAME = TMP.TARGET_TABLE_NAME, 
LIVE_TABLE.TARGET_DATA_LAKE_PATH = TMP.TARGET_DATA_LAKE_PATH, 
LIVE_TABLE.ADF_TRIGGER_NAME = TMP.ADF_TRIGGER_NAME,
LIVE_TABLE.SOURCE_DATABASE_NAME = TMP.SOURCE_DATABASE_NAME,
LIVE_TABLE.IS_HEDIS_RUN_ID_TABLE = TMP.IS_HEDIS_RUN_ID_TABLE,
LIVE_TABLE.IS_PARTITION_BY_STRING = TMP.IS_PARTITION_BY_STRING,
LIVE_TABLE.PARTITION_BY_STRING_COLUMN_NAME = TMP.PARTITION_BY_STRING_COLUMN_NAME,
LIVE_TABLE.TARGET_CONTAINER_NAME = TMP.TARGET_CONTAINER_NAME
FROM UTIL.TMP_ADF_COPY_CONTROL TMP
WHERE LIVE_TABLE.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY
;

SELECT 'Finished updating the static data table UTIL.ADF_COPY_CONTROL';

